/**
 * Error transport for remote boundaries (Electron IPC, remote-control WebSocket).
 *
 * Both boundaries reduce a rejected call to its message text, which destroys the marker properties
 * that the renderer uses to recognise recoverable conditions such as a missing working folder.
 * The main process therefore resolves with an envelope instead of rejecting, and the renderer
 * rebuilds a typed error from it.
 */

const BRIDGE_ERROR_ENVELOPE_KEY = '__md2BridgeError'
const BRIDGE_ERROR_FIELDS = ['rootPath', 'workingFolder']
const NOT_A_GIT_REPOSITORY_ERROR = 'not-a-git-repository'

function errorFields(error) {
    const fields = {}

    for (const field of BRIDGE_ERROR_FIELDS) {
        const value = error[field]
        if (typeof value === 'string') fields[field] = value
    }

    return fields
}

/** Build the transport payload for an error, keeping its `code` and declared extra fields. */
export function serializeBridgeError(error) {
    if (!(error instanceof Error)) {
        return { [BRIDGE_ERROR_ENVELOPE_KEY]: { fields: {}, message: String(error), name: 'Error' } }
    }

    const payload = { fields: errorFields(error), message: error.message, name: error.name }
    if (typeof error.code === 'string') payload.code = error.code

    return { [BRIDGE_ERROR_ENVELOPE_KEY]: payload }
}

/** True when a resolved bridge result actually carries a failure. */
export function isBridgeErrorEnvelope(value) {
    if (!value || typeof value !== 'object') return false

    const payload = value[BRIDGE_ERROR_ENVELOPE_KEY]

    return !!payload
        && typeof payload === 'object'
        && (payload.code === undefined || typeof payload.code === 'string')
        && !!payload.fields
        && typeof payload.fields === 'object'
        && !Array.isArray(payload.fields)
        && Object.values(payload.fields).every((field) => typeof field === 'string')
        && typeof payload.message === 'string'
        && typeof payload.name === 'string'
}

/** Read the payload out of an envelope, or null when the value is an ordinary result. */
export function bridgeErrorPayload(value) {
    if (!value || typeof value !== 'object' || !Object.hasOwn(value, BRIDGE_ERROR_ENVELOPE_KEY)) return null
    if (!isBridgeErrorEnvelope(value)) throw new Error('Invalid bridge error envelope')

    return value[BRIDGE_ERROR_ENVELOPE_KEY]
}

export { BRIDGE_ERROR_ENVELOPE_KEY, BRIDGE_ERROR_FIELDS, NOT_A_GIT_REPOSITORY_ERROR }

/**
 * Error codes for local file links clicked in agent conversations.
 *
 * Codes survive the bridge error envelope, so the renderer can tell expected link validation
 * failures apart from unexpected launch failures.
 */

export const INVALID_LOCAL_FILE_LINK_ERROR = 'invalid-local-file-link'
export const LOCAL_FILE_LINK_OUTSIDE_REPOSITORY_ERROR = 'local-file-link-outside-repository'

/** Build an error that carries a local file link error code. */
export function localFileLinkError(code, message) {
    const error = new Error(message)
    error.code = code

    return error
}

/** True when an error carries the given local file link error code. */
export function isLocalFileLinkError(error, code) {
    return !!error && typeof error === 'object' && error.code === code
}

import { bridgeErrorPayload, type BridgeErrorPayload } from '../../../shared/bridge_errors.mjs'
import { MISSING_WORKING_FOLDER_ERROR, MissingWorkingFolderError } from './data_types'

/**
 * Rebuilds a typed error from a transport payload.
 *
 * Electron IPC and the remote-control socket both reduce a rejection to its message text, so
 * marker properties such as `code` and `workingFolder` only survive as an explicit payload.
 */
export function rehydrateBridgeError(payload: BridgeErrorPayload): Error {
    if (payload.code === MISSING_WORKING_FOLDER_ERROR && typeof payload.fields.workingFolder === 'string') {
        return new MissingWorkingFolderError(payload.fields.workingFolder)
    }

    const error = new Error(payload.message) as Error & { code?: string }
    error.name = payload.name
    if (payload.code !== undefined) error.code = payload.code
    Object.assign(error, payload.fields)

    return error
}

/** Returns the bridge result unchanged, or throws the rehydrated error it carries. */
export function unwrapBridgeResult<T>(result: T): T {
    const payload = bridgeErrorPayload(result)
    if (!payload) return result

    throw rehydrateBridgeError(payload)
}

function isPromiseLike(value: unknown): value is PromiseLike<unknown> {
    if (!value || (typeof value !== 'object' && typeof value !== 'function')) return false

    return typeof (value as { then?: unknown }).then === 'function'
}

async function unwrapBridgePromise(result: PromiseLike<unknown>) {
    return unwrapBridgeResult(await result)
}

/** Wraps every method of a bridge so failures resolved as envelopes are thrown as typed errors. */
export function withBridgeErrorRehydration<T extends object>(bridge: T): T {
    const wrapped: Record<string, unknown> = {}

    for (const key of Object.keys(bridge) as (keyof T & string)[]) {
        const value = bridge[key]
        if (typeof value !== 'function') {
            wrapped[key] = value
            continue
        }

        wrapped[key] = (...parameters: unknown[]) => {
            const result = (value as (...args: unknown[]) => unknown).apply(bridge, parameters)
            if (!isPromiseLike(result)) return unwrapBridgeResult(result)

            return unwrapBridgePromise(result)
        }
    }

    return wrapped as T
}

const rehydratedPreloadBridges = new WeakMap<object, object>()

/** Returns one cached rehydrating wrapper per preload bridge instance, so repeated lookups keep a stable identity. */
export function rehydratedPreloadBridge<T extends object>(bridge: T): T {
    const cached = rehydratedPreloadBridges.get(bridge)
    if (cached) return cached as T

    const wrapped = withBridgeErrorRehydration(bridge)
    rehydratedPreloadBridges.set(bridge, wrapped)

    return wrapped
}

